/** Supported Pixel Studio prompt formats. Shared by the HTTP and Codex adapters. */
export const MAX_PROMPT_BYTES = 2 * 1024 * 1024;
export const MAX_OUTPUT_BYTES = 4 * 1024 * 1024;
export const MAX_PREVIEW_BYTES = 1024 * 1024;
export const MAX_PREVIEW_COUNT = 2;

/** Only bounded, inline PNGs generated by the editor; never paths or remote URLs. */
export function readPreviewImages(images = []) {
  if (!Array.isArray(images) || images.length > MAX_PREVIEW_COUNT) throw new Error('Provide at most two PNG previews.');
  return images.map(image => {
    if (typeof image !== 'string' || image.length > Math.ceil(MAX_PREVIEW_BYTES * 4 / 3) + 24 || !/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(image)) throw new Error('Invalid PNG preview.');
    const bytes = Buffer.from(image.slice('data:image/png;base64,'.length), 'base64');
    if (bytes.length < 33 || bytes.length > MAX_PREVIEW_BYTES || bytes.subarray(0,8).toString('hex') !== '89504e470d0a1a0a' || bytes.readUInt32BE(8) !== 13 || bytes.subarray(12,16).toString() !== 'IHDR') throw new Error('Invalid PNG header.');
    const width=bytes.readUInt32BE(16), height=bytes.readUInt32BE(20);
    if (!width || !height || width>1024 || height>1024) throw new Error('Preview dimensions exceed 1024 pixels.');
    return bytes;
  });
}

export function isPixelPrompt(prompt) {
  return typeof prompt === 'string' && prompt.trim().length > 0
    && Buffer.byteLength(prompt) <= MAX_PROMPT_BYTES
    && /\b(?:PXA [12]|PXAPATCH 2|PXAINPAINT 1|PXAPALETTE 1)\b/.test(prompt);
}
